-- What each version was built against: every package the sandbox that checked
-- and compiled it had installed, at its exact version, as a lockfile records
-- it. Replaces the Vercel Sandbox snapshot's id, which named the machine, not
-- what the app was built with. Empty for versions saved before either.
alter table public.versions add column packages jsonb;

-- The versions recorded by snapshot: its packages, read from the snapshot
-- itself (2026-10-24).
update public.versions
